function validLocale(value: unknown): value is Locale {
  return value === "en" || value === "zh-TW";
}

function browserLocale(): Locale {
  if (typeof navigator === "undefined") return "en";
  const languages = navigator.languages?.length ? navigator.languages : [navigator.language];
  for (const language of languages) {
    if (/^zh-(TW|Hant)(-|$)/i.test(language)) return "zh-TW";
    if (/^en(-|$)/i.test(language)) return "en";
  }
  return "en";
}

/** Browser-only choice for signed-out and local sign-ins (CAD-1331). Not an account write. */
const LOCAL_LOCALE_KEY = "cadence-locale";

function storedLocalLocale(): Locale | null {
  try {
    const value = window.localStorage.getItem(LOCAL_LOCALE_KEY);
    return validLocale(value) ? value : null;
  } catch {
    return null;
  }
}

function storeLocalLocale(value: Locale | null): void {
  try {
    if (value === null) window.localStorage.removeItem(LOCAL_LOCALE_KEY);
    else window.localStorage.setItem(LOCAL_LOCALE_KEY, value);
  } catch {
    // Storage unavailable: the choice still applies for this page view.
  }
}

function decodePreferences(value: unknown): Preferences {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new Error("Invalid locale preferences response");
  }
  const organizationLocale = "organization_locale" in value ? value.organization_locale : null;
  const userLocale = "user_locale" in value ? value.user_locale : null;
  return {
    organization_locale: validLocale(organizationLocale) ? organizationLocale : null,
    user_locale: validLocale(userLocale) ? userLocale : null,
  };
}

async function readPreferences(operation: PrivateOperation): Promise<Preferences> {
  const response = await privateFetch("/api/locale", { headers: { "X-Cadence-Board": "1" } }, operation);
  if (!response.ok) throw new Error(`Locale preferences unavailable (${response.status})`);
  const value: unknown = await response.json();
  operation.assertCurrent();
  return decodePreferences(value);
}

async function writePreference(scope: Scope, locale: Locale | null, operation: PrivateOperation): Promise<Preferences> {
  const response = await privateFetch("/api/locale", {
    method: "POST",
    headers: { "Content-Type": "application/json", "X-Cadence-Board": "1" },
    body: JSON.stringify({ scope, locale }),
  }, operation);
  if (!response.ok) throw new Error(`Locale preference write refused (${response.status})`);
  const value: unknown = await response.json();
  operation.assertCurrent();
  return decodePreferences(value);
}

interface LocaleContextValue {
  locale: Locale;
  userLocale: Locale | null;
  organizationLocale: Locale | null;
  isHostedUser: boolean;
  canSetOrganizationLocale: boolean;
  t: (english: string) => string;
  setSession: (meta: Meta | null) => void;
  setPreference: (scope: Scope, locale: Locale | null) => Promise<void>;
  formatDate: (value: string | number | Date, options?: Intl.DateTimeFormatOptions) => string;
  formatNumber: (value: number, options?: Intl.NumberFormatOptions) => string;
  formatRelativeTime: (value: string | number | Date, now?: number) => string;
}

const LocaleContext = createContext<LocaleContextValue | null>(null);

export function translateUiText(english: string, locale: Locale): string {
  return locale === "zh-TW" ? (zhTW[english] ?? english) : english;
}

export function LocaleProvider({ children }: { children: ReactNode }) {
  const [meta, setMeta] = useState<Meta | null>(null);
  const [storedPreferences, setStoredPreferences] = useState<{ identity: string; value: Preferences } | null>(null);
  const [localLocale, setLocalLocale] = useState<Locale | null>(storedLocalLocale);
  const requestId = useRef(0);
  const identity = meta?.hosted === true && meta.signed_in === true && meta.session?.origin === "public" && meta.session.user?.sub
    ? `${meta.session.user.sub}:${meta.session.id}`
    : null;

  const setSession = useCallback((next: Meta | null) => setMeta(next), []);

  useEffect(() => {
    const request = ++requestId.current;
    if (!identity || !privateReadsAllowed()) return;
    const operation = beginPrivateOperation();
    void readPreferences(operation)
      .then((next) => {
        operation.assertCurrent();
        if (request === requestId.current) setStoredPreferences({ identity, value: next });
      })
      .catch(() => {
        if (!operation.signal.aborted && request === requestId.current) setStoredPreferences(null);
      })
      .finally(() => operation.dispose());
    return () => {
      requestId.current += 1;
      operation.dispose();
    };
  }, [identity]);

  const preferences = storedPreferences?.identity === identity ? storedPreferences.value : null;
  const locale: Locale = identity
    ? preferences?.user_locale ?? preferences?.organization_locale ?? browserLocale()
    : localLocale ?? browserLocale();
  useEffect(() => {
    document.documentElement.lang = locale;
  }, [locale]);

  const setPreference = useCallback(async (scope: Scope, value: Locale | null) => {
    if (identity === null) {
      // Signed-out and local sign-ins: browser-only, no HTTP and no authority.
      if (scope !== "user") throw new Error("Organization language needs a hosted operator");
      storeLocalLocale(value);
      setLocalLocale(value);
      return;
    }
    const generation = ++requestId.current;
    const writeIdentity = identity;
    await withPrivateOperation(async (operation) => {
      const next = await writePreference(scope, value, operation);
      operation.assertCurrent();
      // A retired save must neither resolve successfully nor evict a later identity's preferences.
      if (generation === requestId.current) setStoredPreferences({ identity: writeIdentity, value: next });
    });
  }, [identity]);

  const context = useMemo<LocaleContextValue>(() => ({
    locale,
    userLocale: identity ? preferences?.user_locale ?? null : localLocale,
    organizationLocale: preferences?.organization_locale ?? null,
    isHostedUser: identity !== null,
    canSetOrganizationLocale: identity !== null && meta?.session?.user?.role === "operator",
    t: (english) => translateUiText(english, locale),
    setSession,
    setPreference,
    formatDate: (value, options) => new Intl.DateTimeFormat(locale, options).format(value instanceof Date ? value : new Date(value)),
    formatNumber: (value, options) => new Intl.NumberFormat(locale, options).format(value),
    formatRelativeTime: (value, now = Date.now()) => {
      const seconds = (new Date(value instanceof Date ? value.getTime() : value).getTime() - now) / 1000;
      const units: [Intl.RelativeTimeFormatUnit, number][] = [["year", 31_536_000], ["month", 2_592_000], ["week", 604_800], ["day", 86_400], ["hour", 3_600], ["minute", 60], ["second", 1]];
      const [unit, size] = units.find(([, unitSeconds]) => Math.abs(seconds) >= unitSeconds) ?? ["second", 1];
      return new Intl.RelativeTimeFormat(locale, { numeric: "auto" }).format(Math.round(seconds / size), unit);
    },
  }), [identity, locale, localLocale, meta?.session?.user?.role, preferences, setPreference, setSession]);

  return (
    <LocaleContext.Provider value={context}>
      <LocaleTextProvider value={context.t}>{children}</LocaleTextProvider>
    </LocaleContext.Provider>
  );
}

